import { createContext, useContext, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react'
import { Link, NavLink, Route, Routes, useNavigate, useParams } from 'react-router-dom'
import { ArrowRight, ArrowUpRight, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, Clock3, Copy, CreditCard, Download, Facebook, FileCheck2, LockKeyhole, MapPin, Menu, ShieldCheck, Sparkles, Trash2, Trophy, UserRound, X } from 'lucide-react'
import { supabase, type Booking, peso, hourLabel } from './lib/supabase'

type User = { id: string; email?: string; user_metadata?: { full_name?: string } }
type CourtRates = Record<number, number>
const CourtPricingContext=createContext<{rates:CourtRates;refresh:()=>Promise<void>}>({rates:{1:250,2:350},refresh:async()=>{}})
const useCourtPricing=()=>useContext(CourtPricingContext)
const BookingRulesContext=createContext<(path:string)=>void>(()=>{})
const compactHourLabel=(hour:number)=>`${hour%12||12}${hour<12?'AM':'PM'}`
const slotRanges=(hours:number[])=>{const sorted=[...new Set(hours)].sort((a,b)=>a-b);const ranges:number[][]=[];for(const hour of sorted){const last=ranges.at(-1);if(last&&hour===last.at(-1)!+1)last.push(hour);else ranges.push([hour])}return ranges.map(range=>`${hourLabel(range[0])} – ${hourLabel(range.at(-1)!+1)}`).join(', ')}
type CourtSelection={court_id:number;hours:number[];hourly_rate?:number;subtotal?:number}
const courtLabel=(court:number)=>court===1?'The Basic · Court 1':'The Pro · Court 2'
const bookingSelections=(booking:{court_id:number;selected_hours?:number[]|null;start_hour:number;duration_hours:number;court_selections?:CourtSelection[]|null}):CourtSelection[]=>booking.court_selections?.length?booking.court_selections:[{court_id:booking.court_id,hours:booking.selected_hours?.length?booking.selected_hours:Array.from({length:booking.duration_hours},(_,i)=>booking.start_hour+i)}]
const bookingTimeLabel=(booking:{court_id:number;selected_hours?:number[]|null;start_hour:number;duration_hours:number;court_selections?:CourtSelection[]|null})=>{const selections=bookingSelections(booking);return selections.map(selection=>selections.length>1?`${courtLabel(selection.court_id)}: ${slotRanges(selection.hours)}`:slotRanges(selection.hours)).join(' · ')}
const bookingCourtsLabel=(booking:{court_id:number;selected_hours?:number[]|null;start_hour:number;duration_hours:number;court_selections?:CourtSelection[]|null})=>bookingSelections(booking).map(selection=>courtLabel(selection.court_id)).join(' + ')
const bookingCourtHours=(booking:{court_id:number;selected_hours?:number[]|null;start_hour:number;duration_hours:number;court_selections?:CourtSelection[]|null})=>bookingSelections(booking).reduce((sum,selection)=>sum+selection.hours.length,0)
async function edgeFunctionErrorMessage(error:unknown){const fnError=error as {message?:string;context?:Response};const fallback=fnError?.message||'Could not send confirmation email.';if(fnError?.context&&typeof fnError.context.json==='function'){try{const body=await fnError.context.json() as {error?:string;message?:string};return body.error||body.message||fallback}catch{}}return fallback}
async function sendBookingConfirmationEmail(bookingId:string){if(!supabase)return {error:new Error('Supabase is not configured.')};const {data,error:sessionError}=await supabase.auth.refreshSession();if(sessionError||!data.session)return {error:new Error('Your admin session expired. Sign out and sign in again, then retry.')};return supabase.functions.invoke('booking-confirmation-email',{body:{booking_id:bookingId},headers:{Authorization:`Bearer ${data.session.access_token}`}})}
function GcashNumber(){const [copied,setCopied]=useState(false);async function copy(){try{await navigator.clipboard.writeText('09052692785');setCopied(true);window.setTimeout(()=>setCopied(false),1800)}catch{setCopied(false)}}return <div className="gcash-number-row"><div><small>GCASH NUMBER · M* AN***A S.</small><b>09052692785</b></div><button type="button" className="gcash-copy-button" onClick={copy}>{copied?<Check size={14}/>:<Copy size={14}/>} {copied?'Copied':'Copy number'}</button></div>}
const localDate = (daysAhead=0) => { const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return new Date(Date.UTC(Number(p.year),Number(p.month)-1,Number(p.day)+daysAhead)).toISOString().slice(0,10) }

export default function App() {
  const navigate=useNavigate()
  const [user, setUser] = useState<User | null>(null)
  const [admin, setAdmin] = useState(false)
  const [loading, setLoading] = useState(true)
  const [courtRates,setCourtRates]=useState<CourtRates>({1:250,2:350})
  const [bookingRulesPath,setBookingRulesPath]=useState<string|null>(null)
  const openBookingRules=(path:string)=>setBookingRulesPath(path)
  const configured = Boolean(supabase)
  async function refreshCourtRates(){if(!supabase)return;const {data}=await supabase.from('courts').select('id,hourly_rate').in('id',[1,2]);if(data){const values={1:250,2:350};for(const court of data)values[court.id as 1|2]=Number(court.hourly_rate)||values[court.id as 1|2];setCourtRates(values)}}
  useEffect(()=>{void refreshCourtRates()},[])
  useEffect(() => {
    if (!supabase) { setLoading(false); return }
    supabase.auth.getSession().then(({ data }) => setUser(data.session?.user as User ?? null)).finally(() => setLoading(false))
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => { setUser(session?.user as User ?? null) })
    return () => subscription.unsubscribe()
  }, [])
  useEffect(() => {
    if (!user || !supabase) { setAdmin(false); return }
    supabase.from('profiles').select('is_admin').eq('id', user.id).maybeSingle().then(({ data }) => setAdmin(Boolean(data?.is_admin)))
  }, [user])
  const signOut = async () => { await supabase?.auth.signOut(); setUser(null); location.href = '/' }
  if (loading) return <div className="loading-page"><div className="spinner" />Loading Stag Base…</div>
  return <CourtPricingContext.Provider value={{rates:courtRates,refresh:refreshCourtRates}}><BookingRulesContext.Provider value={openBookingRules}>
    <Header user={user} admin={admin} signOut={signOut} />
    {!configured && <div className="setup-banner"><span>Demo preview</span> Connect Supabase to enable sign in, live availability and bookings. <a href="#setup">See setup</a></div>}
    <Routes>
      <Route path="/" element={<Home />} />
      <Route path="/courts" element={<Courts />} />
      <Route path="/login" element={<AuthPage mode="login" />} />
      <Route path="/register" element={<AuthPage mode="register" />} />
      <Route path="/reset-password" element={<AuthPage mode="reset" />} />
      <Route path="/book" element={<BookingPage />} />
      <Route path="/booking/group/:groupId" element={<BookingGroupDetailsPage />} />
      <Route path="/booking/:id" element={<BookingDetailsPage user={user} />} />
      <Route path="/dashboard" element={user ? <Dashboard user={user} /> : <AuthGate />} />
      <Route path="/admin" element={user && admin ? <AdminDashboard /> : <AuthGate admin />} />
      <Route path="*" element={<Home />} />
    </Routes>
    <Footer />
    {bookingRulesPath&&<BookingRulesDialog onClose={()=>setBookingRulesPath(null)} onContinue={()=>{const path=bookingRulesPath;setBookingRulesPath(null);navigate(path)}}/>}
  </BookingRulesContext.Provider></CourtPricingContext.Provider>
}

function BookLink({to,className,children,ariaLabel}:{to:string;className?:string;children:React.ReactNode;ariaLabel?:string}){const showRules=useContext(BookingRulesContext);return <Link to={to} className={className} aria-label={ariaLabel} onClick={event=>{event.preventDefault();showRules(to)}}>{children}</Link>}

