    <section className="landing-social-links" aria-label="Find and follow Stag Base"><a className="button button-dark" href="https://maps.app.goo.gl/FECaCqWTpP8kEeLb6" target="_blank" rel="noopener noreferrer"><MapPin size={16}/> Google Maps location <ArrowUpRight size={15}/></a><a className="button button-outline" href="https://www.facebook.com/profile.php?id=61591605945094" target="_blank" rel="noopener noreferrer"><Facebook size={16}/> Facebook profile <ArrowUpRight size={15}/></a></section>
